    /**
     * Tests creating a new Building.
     *
     * @return    Building
     */
    public Building testCreate() throws Throwable {
    Building entity = null;

    LOGGER.info( "BuildingTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a Building");

    StringBuilder msg = new StringBuilder( "-- Failed to create a Building" );

    try {
        entity = service.createBuilding( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getBuildingId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a Building with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

    /**
     * Tests reading a Building.
     *
     * @return    Building
     */
    public Building testRead() throws Throwable {
    LOGGER.info( "BuildingTest:testRead()" );
    LOGGER.info( "-- Reading a previously created Building" );

    Building entity = null;
    StringBuilder msg = new StringBuilder( "-- Failed to read Building with primary key" );
    msg.append( theId );

    try {
        entity = service.getBuilding( new BuildingFetchOneSummary(theId) );

        assertNotNull( entity,msg.toString() );

        // for use later
        theId = entity.getBuildingId();

        LOGGER.info( "-- Successfully found Building " + entity.toString() );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + " : " + e );

        throw e;
    }

    return( entity );
}

    /**
     * Tests updating a Building.
     *
     * @return    Building
     */
    public Building testUpdate() throws Throwable {
    LOGGER.info( "BuildingTest:testUpdate()" );
    LOGGER.info( "-- Attempting to update a Building." );

    StringBuilder msg = new StringBuilder( "Failed to update a Building : " );
    Building entity = null;

    try {
        UpdateBuildingCommand updateCommand = this.generateUpdateCommand();

        // apply the current id as to update the fields of the current entity
        updateCommand.setBuildingId( theId );

        assertNotNull( updateCommand, msg.toString() );

        LOGGER.info( "-- Now updating the created Building." );

        entity = service.updateBuilding( updateCommand );

        assertNotNull( entity, msg.toString()  );

        LOGGER.info( "-- Successfully saved Building - " + entity.toString() );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + " : primarykey-" + theId + " : entity-" +  entity + " : " + e );

        throw e;
    }

    return( entity );
}

    /**
     * Tests deleting a Building.
     */
    public void testDelete() throws Throwable {
    LOGGER.info( "BuildingTest:testDelete()" );
    LOGGER.info( "-- Deleting a previously created Building." );

    try {
        DeleteBuildingCommand deleteCommand = new DeleteBuildingCommand( theId );

        service.delete( deleteCommand );

        LOGGER.info( "-- Successfully deleted Building with primary key " + theId );
    }
    catch ( Throwable e ) {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( "-- Failed to delete Building with primary key " + theId );

        throw e;
    }
}

    /**
     * Tests getting all Buildings.
     *
     * @return    Collection
     */
    public List<Building> testGetAll() throws Throwable {
    LOGGER.info( "BuildingTest:testGetAll() - Retrieving Collection of Buildings:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Building : " );
    List<Building> collection  = null;

    try {
        // call the static get method on the BuildingService
        collection = service.getAllBuilding();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Building currEntity  = null;
            Iterator<Building> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getBuildingId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

